j:jelly.script:
var ${jvar_name}_selectTable = new GwtSelectTable('${jvar_name}_tbl');
${jvar_name}_selectTable.initZones('${jvar_name}_tbl');
${jvar_name}_selectTable.setMultiSelect(true);
var ${jvar_name}_leftzone = ${jvar_name}_selectTable.getList('${jvar_name}_left');
var ${jvar_name}_rightzone = ${jvar_name}_selectTable.getList('${jvar_name}_right');

${jvar_name}_selectTable.on("aftermove", ${jvar_name}_afterMove);
${jvar_name}_selectTable.on("aftercopy", ${jvar_name}_afterCopy);

${jvar_name}_selectTable.setDblClickTarget('${jvar_name}_left', '${jvar_name}_right');
${jvar_name}_selectTable.setDblClickTarget('${jvar_name}_right', '${jvar_name}_left');

function ${jvar_name}_afterMove() {
  ${jvar_aftermove};
}

function ${jvar_name}_afterCopy() {
  ${jvar_aftercopy};
}

// define this in ui page
${jvar_name}_populate(${jvar_name}_leftzone, ${jvar_name}_rightzone);	

function ${jvar_name}_hideMoveToLeftButton() {
  var el = gel('${jvar_name}_move_left_text');
  el.style.display="none";

  el = gel('${jvar_name}_move_left_button');
  el.style.display="none";

  el = gel('${jvar_name}_move_right_text');
  el.style.display="";

  el = gel('${jvar_name}_move_right_button');
  el.style.display="";
}

function ${jvar_name}_hideMoveToRightButton() {
  var el = gel('${jvar_name}_move_right_text');
  el.style.display="none";

  el = gel('${jvar_name}_move_right_button');
  el.style.display="none";

  el = gel('${jvar_name}_move_left_text');
  el.style.display="";

  el = gel('${jvar_name}_move_left_button');
  el.style.display="";
}
